/**
 * The complete client-to-server union, discriminated by `type`. Nothing in it mutates a resource: the stream
 * subscribes, paces, and probes, and every state change is a REST write. An unknown `type` is a protocol error,
 * never a silent no-op, so a client cannot believe it subscribed when it did not.
 */
export type WsClientMessage = 
    | WsHello
    | WsSubscribe
    | WsUnsubscribe
    | WsAck
    | WsPing
    | WsBye;

/**
 * First server frame after the upgrade, before any `subscription_state`. It hands the client the epoch and the
 * numbers the conversation is bounded by, so a client learns it is on a different server (epoch change) before
 * it sends a single subscribe.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsWelcome {
    type: "welcome";
    protocol: "harness.v1";
    epoch: string;
    at: number;
    limits: WsStreamLimits;
}

/**
 * The reconciliation anchor for one subscription, and the reason no snapshot frame is needed: it is the atomic
 * state at registration. `revisions` plus `sequence` tell a client exactly which later frames are already
 * covered by a REST read it issues afterwards, and `replayed_frames` counts what the server re-sent from a
 * retained buffer, so a resuming client knows whether it received history or must re-read.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsSubscriptionState {
    type: "subscription_state";
    subscription_id: string;
    scope: WsSubscriptionScope;
    epoch: string;
    /** Always 0 for a new subscription; frames above it are new information. */
    sequence: number;
    cursor: string;
    /**
     * The atomic counter baseline at registration: one `WsRevisionRecord` per kind THIS scope publishes, keyed
     * by resource kind and instance id (see `StreamResourceKind` for the per-scope sets). A REST read issued
     * after this frame that returns a revision at or above the matching record already reflects everything the
     * stream has said, so any frame at or below `sequence` is redundant for that kind. Comparisons are per
     * kind, per id, per epoch - never across kinds and never across epochs.
     */
    revisions: WsRevisionRecord[];
    filters_applied?: WsSubscriptionFilters;
    replayed_frames?: number;
    /**
     * The authoritative kind set THIS subscription may send, after its scope and applied filters. It is stated
     * per connection rather than assumed from the document, so a client knows whether `run.event` is coming
     * (the `events` filter) and can ignore a kind it was never promised. Adding a kind means re-subscribing,
     * never renegotiating.
     */
    publishes: WsUpdateKind[];
}

/**
 * One question stopped waiting: `reason` says which of the honest outcomes happened, so a client clears the
 * card without guessing whether the run was cancelled, the answer arrived, or the request expired.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsActionClosed {
    request_id: string;
    reason: "answered" | "expired" | "cancelled" | "ended";
}

/**
 * `session.updated` carries `session` (a metadata patch) and no other payload field.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateSession {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "session.updated";
    at: number;
    session: SessionStatePatch;
}

/**
 * `turn.upsert` carries `turn`, one whole row keyed by its own `id`, and no other payload field. The row id is
 * inside the row, so a redundant `turn_id` is rejected: there is one place a turn identity can come from.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateTurnUpsert {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "turn.upsert";
    at: number;
    turn: TurnSummary;
}

/**
 * `turn.removed` is PURE INVALIDATION: `turn_id` only, no body, because the row is gone and a re-read of `GET
 * .../turns` is the cheapest truth. It is not the `ids` form, because exactly one row is addressed.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateTurnRemoved {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "turn.removed";
    at: number;
    turn_id: string;
}

/**
 * `display.ops` carries `turn_id` AND `ops`: the ops themselves are addressed by section, node, step, and block
 * id, so the turn id is required for routing but never duplicated inside each op.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateDisplayOps {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "display.ops";
    at: number;
    turn_id: string;
    ops: TurnDisplayOp[];
}

/**
 * `usage.updated` carries `usage_patch`; `turn_id` is optional inside it or beside it, because a turn figure
 * and a session figure share one kind and the patch itself says which it is.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateUsage {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "usage.updated";
    at: number;
    turn_id?: string;
    usage_patch: UsagePatch;
}

/**
 * `action.opened` carries `action`, one ready-to-answer question, and no other payload field.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateActionOpened {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "action.opened";
    at: number;
    action: PendingAction;
}

/**
 * `action.closed` carries `action_closed` (the request id plus which honest outcome ended it) and no other
 * payload field, so a client clears exactly one card.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateActionClosed {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "action.closed";
    at: number;
    action_closed: WsActionClosed;
}

/**
 * `thread.upsert` carries `thread`, one whole roster row, and no other payload field. Roster rows carry
 * transcript SIGNALS only, so this never becomes a transcript transfer.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateThreadUpsert {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "thread.upsert";
    at: number;
    thread: ThreadSummary;
}

/**
 * `thread.removed` is PURE INVALIDATION: `thread_id` only, no body.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateThreadRemoved {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "thread.removed";
    at: number;
    thread_id: string;
}

/**
 * `transcript.updated` carries `transcript` (counts plus a revision) and no other payload field. Message bodies
 * are never streamed: a client that is showing this transcript re-pages the messages route.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateTranscript {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "transcript.updated";
    at: number;
    transcript: TranscriptSignal;
}

/**
 * `tool.registry_updated` is PURE INVALIDATION with a non-empty `ids` list (the tool names that changed). It
 * carries no descriptor, because the toolbox page is one bounded read away and is the truth.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateToolRegistry {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "tool.registry_updated";
    at: number;
    ids: string[];
}

/**
 * `agent.registry_updated` is PURE INVALIDATION with a non-empty `ids` list (the roster keys that changed).
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateAgentRegistry {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "agent.registry_updated";
    at: number;
    ids: string[];
}

/**
 * `run.event` carries `turn_id` AND `events`, and is only ever sent to a `session` subscription whose `events`
 * filter is true. This is the one kind that ships verbatim recorded bytes, and it is opt-in debug traffic.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateRunEvent {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "run.event";
    at: number;
    turn_id: string;
    events: TurnEventRow[];
}

/**
 * `catalogue.updated` carries `catalogue` (which global collection moved) AND a non-empty `ids` list. It is
 * invalidation with names, so a client re-reads one page or one identified resource, never all three
 * catalogues.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateCatalogue {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "catalogue.updated";
    at: number;
    catalogue: "harnesses" | "agents" | "tools";
    ids: string[];
}

/**
 * `config.updated` carries NO payload field at all, and that is deliberate: the global configuration is one
 * named resource with no id set, so the subscription itself identifies what changed and `revision` in `GET
 * /config` says whether the client is already current. A frame with `ids` here is invalid, because it would
 * imply a set that does not exist.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsUpdateConfig {
    type: "update";
    subscription_id: string;
    sequence: number;
    cursor: string;
    kind: "config.updated";
    at: number;
}

/**
 * One bounded delta on one subscription, discriminated by `kind`, with exactly one variant per kind. `sequence`
 * is monotonic per subscription and `cursor` is its opaque resume token, so a client detects a gap by
 * arithmetic rather than by inference and a server that dropped frames says so instead of leaving the client
 * with a silently wrong view. KIND TO PAYLOAD (exhaustive, machine-enforced by the variants): `session.updated`
 * requires `session`; `turn.upsert` requires `turn`; `turn.removed` requires `turn_id` and nothing else;
 * `display.ops` requires `turn_id` and `ops`; `usage.updated` requires `usage_patch` and may also carry
 * `turn_id`; `action.opened` requires `action`; `action.closed` requires `action_closed`; `thread.upsert`
 * requires `thread`; `thread.removed` requires `thread_id`; `transcript.updated` requires `transcript`;
 * `records.updated` requires `records`; `tool.registry_updated` requires a non-empty `ids`;
 * `agent.registry_updated` requires a non-empty `ids`; `run.event` requires `turn_id` and `events`;
 * `catalogue.updated` requires `catalogue` and a non-empty `ids`; `config.updated` requires no payload. Every
 * variant forbids every other payload field, so no frame can be both a body and an invalidation. A frame that
 * names a resource a client is not showing is ignored, which is what makes one shared session scope cheap for
 * several panes.
 */
export type WsUpdate = 
    | WsUpdateSession
    | WsUpdateTurnUpsert
    | WsUpdateTurnRemoved
    | WsUpdateDisplayOps
    | WsUpdateUsage
    | WsUpdateActionOpened
    | WsUpdateActionClosed
    | WsUpdateThreadUpsert
    | WsUpdateThreadRemoved
    | WsUpdateTranscript
    | WsUpdateRecords
    | WsUpdateToolRegistry
    | WsUpdateAgentRegistry
    | WsUpdateRunEvent
    | WsUpdateCatalogue
    | WsUpdateConfig;

/**
 * The only recovery frame, and the only place a client is told to re-read. It carries a reason, the current
 * epoch and cursor to resume from, and at most 16 resource links. It NEVER carries a session, a snapshot, an
 * event array, or a display tree, which is the rule that keeps the stream from reintroducing the payload class
 * the resource design removed.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsResyncRequired {
    type: "resync_required";
    subscription_id: string;
    /**
     * Exactly three causes, and each one says what the client must do. `cursor_expired` = the resume cursor is
     * older than the replay window (the advertised `replay_frames` / `replay_seconds`), so the client re-reads
     * the listed resources. `epoch_mismatch` = the cursor came from a previous server lifetime, so every
     * retained position is dead. `frames_dropped` = the server is still live and this subscription lost frames
     * it could not deliver (send-queue backpressure or an expired ack), so the client re-reads the listed
     * resources and keeps its cursor at `cursor`. A filter problem is NOT a reason here: it is reported by
     * `WsProtocolError{ code: unsupported_filter }` at subscribe time, which is the single place that condition
     * is ever stated.
     */
    reason: "cursor_expired" | "epoch_mismatch" | "frames_dropped";
    epoch: string;
    /** The cursor a client resumes FROM, which is the oldest position still retained. */
    cursor: string;
    /** How many frames this subscription can no longer receive, so a client can bound its re-reads. */
    lost_frames?: number;
    resources: WsResourceLink[];
}

/**
 * A protocol-level problem, reported as a frame rather than a status code because the connection already
 * answered 101. `retryable` distinguishes a client that should resend from one that must not. The connection
 * stays open unless the close code is present, in which case the server closes immediately after this frame.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsProtocolError {
    type: "error";
    /**
     * One code per condition, decided in the single precedence order in `x-websocket.validation_precedence`.
     * `invalid_payload` covers every client-union failure, INCLUDING a `scope` value outside the fixed enum
     * (there is no negotiated scope, so there is no separate scope code). `unknown_resource` is a valid frame
     * whose required session, thread, or turn id does not exist. `unknown_subscription` names a
     * `subscription_id` this connection never opened or already closed. `late_hello` is a `hello` that arrived
     * after the first `subscribe`. `too_many_subscriptions` and `rate_limited` carry the advertised close code
     * when the deployment closes; `frame_too_large` and `internal` may also close.
     */
    code: "invalid_payload" | "unknown_subscription" | "unknown_resource" | "unsupported_filter" | "late_hello" | "too_many_subscriptions" | "frame_too_large" | "rate_limited" | "internal";
    /** Names the offending field or budget, and never contains a credential. */
    message: string;
    subscription_id?: string;
    /**
     * True when resending the same frame after the stated condition changes can succeed (a full subscription
     * budget, an internal stall); false when the frame itself is wrong.
     */
    retryable: boolean;
    /** Present when this error is fatal to the connection. */
    close_code?: number;
}

/**
 * Server keep-alive every `heartbeat_interval_ms`. A client that misses three in a row must assume the
 * connection is gone and reconnect with its cursor, rather than waiting for a TCP timeout that may never fire.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsHeartbeat {
    type: "heartbeat";
    at: number;
}

/**
 * Answer to a `heartbeat` or a client `ping`, echoing the `at` it was given.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface WsPong {
    type: "pong";
    at: number;
}

/**
 * The complete server-to-client union, discriminated by `type`: `welcome`, one `subscription_state` per
 * subscription, `update` deltas, `resync_required` recovery, `error` for protocol problems, and the `heartbeat`
 * / `pong` keep-alive pair. Nothing in it mutates a resource.
 */
export type WsServerMessage = 
    | WsWelcome
    | WsSubscriptionState
    | WsUpdate
    | WsResyncRequired
    | WsProtocolError
    | WsHeartbeat
    | WsPong;
